// TODO (Week 7): I2C master + MPU6050 driver.
//
// Responsibilities, in order:
//   1. Wake the device  - write 0x00 to PWR_MGMT_1 (0x6B)
//   2. Configure ranges - ACCEL_CONFIG (0x1C), GYRO_CONFIG (0x1B)
//   3. Poll at SAMPLE_HZ - burst-read 14 bytes from ACCEL_XOUT_H (0x3B):
//      ax, ay, az, temp, gx, gy, gz  (each big-endian int16)
//   4. Drop temp, emit the 6 axes as one `valid` beat
//
// SCL is generated by dividing clk down to 100 kHz (standard mode). SDA must
// be an open-drain tri-state on the top level:  assign sda = sda_oe ? 1'b0 : 1'bz;

module mpu6050_i2c #(
    parameter CLK_HZ     = 27_000_000,
    parameter I2C_HZ     = 100_000,
    parameter SAMPLE_HZ  = 100,
    parameter DEV_ADDR   = 7'h68        // AD0 tied low
) (
    input  wire        clk,
    input  wire        rst_n,

    // I2C bus (tri-state handled by the parent)
    output wire        scl,
    input  wire        sda_in,
    output wire        sda_out,
    output wire        sda_oe,

    // One beat per completed sample set
    output wire signed [15:0] ax,
    output wire signed [15:0] ay,
    output wire signed [15:0] az,
    output wire signed [15:0] gx,
    output wire signed [15:0] gy,
    output wire signed [15:0] gz,
    output wire        sample_valid,
    output wire        error       // NACK / bus timeout
);

    // Not implemented yet. Until this exists, jepasafe_top can be driven from
    // rtl/tb/ stimulus or a ROM of recorded samples.
    assign scl          = 1'b1;
    assign sda_out      = 1'b1;
    assign sda_oe       = 1'b0;
    assign ax           = 16'sd0;
    assign ay           = 16'sd0;
    assign az           = 16'sd0;
    assign gx           = 16'sd0;
    assign gy           = 16'sd0;
    assign gz           = 16'sd0;
    assign sample_valid = 1'b0;
    assign error        = 1'b0;

endmodule
